-- =====================================================================
-- Seed 01 · Catálogo de proteínas e laticínios + preços das notas do Giuli
-- Fonte: relatório xFácil "Custo de proteínas pelas notas fiscais",
--        Giuli Osteria, 600 notas de 08/08 a 13/10/2026, 362 linhas, R$ 210.028,80
-- Giuli recebe o histórico completo; as demais casas recebem o último preço
-- de cada insumo como REFERÊNCIA (fonte = 'referencia') até a compra própria.
-- Rodar uma única vez, depois das migrações 0001 e 0002.
-- =====================================================================
begin;
set local timezone = 'America/Sao_Paulo';

do $$ begin
  if exists (select 1 from itens_importacao where lote_importacao = 'xfacil-giuli-2026-10-13') then
    raise exception 'Lote xfacil-giuli-2026-10-13 já foi importado';
  end if;
end $$;

-- Casas
on conflict (nome) do nothing;

-- Categorias
on conflict do nothing;

select c, 'insumo', (select id from categorias where nome = 'Proteínas e laticínios' and escopo = 'insumo' and pai_id is null)
  from (values ('Aves'), ('Bovino'), ('Embutidos / curados'), ('Laticínios'), ('Mel'), ('Ovos'), ('Pescados e frutos do mar'), ('Suíno')) v(c)
 where not exists (select 1 from categorias x where x.nome = v.c and x.escopo = 'insumo');

-- Fornecedores
on conflict (nome) do nothing;

-- Insumos canônicos
